def find_critical_and_pseudo_critical_edges(n, edges):
    order = sorted(range(len(edges)), key=lambda i: edges[i][2])

    def mst(skip=None, force=None):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        weight = used = 0
        if force is not None:
            a, b, w = edges[force]
            parent[find(a)] = find(b)
            weight, used = w, 1
        for i in order:
            if i == skip:
                continue
            a, b, w = edges[i]
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                weight += w
                used += 1
        return weight if used == n - 1 else float("inf")

    best = mst()
    critical, pseudo = [], []
    for i in range(len(edges)):
        if mst(skip=i) > best:
            critical.append(i)
        elif mst(force=i) == best:
            pseudo.append(i)
    return [critical, pseudo]
